source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    fill = set()
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != background or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            component = []
            touches_edge = False
            while q:
                r, c = q.popleft()
                component.append((r, c))
                if r in (0, h-1) or c in (0, w-1):
                    touches_edge = True
                for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == background and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            if touches_edge:
                continue
            r0 = min(r for r,c in component); r1 = max(r for r,c in component)
            c0 = min(c for r,c in component); c1 = max(c for r,c in component)
            if len(component) != (r1-r0+1)*(c1-c0+1):
                continue
            if (all(grid[r0-1][c] != background for c in range(c0,c1+1)) and
                all(grid[r1+1][c] != background for c in range(c0,c1+1)) and
                all(grid[r][c0-1] != background for r in range(r0,r1+1)) and
                all(grid[r][c1+1] != background for r in range(r0,r1+1))):
                fill.update(component)
    return [[4 if (r,c) in fill else grid[r][c] for c in range(w)] for r in range(h)]
'''
